import{_ as e,r as n,o,c,e as s,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const q=JSON.parse('{"title":"{% ajaxPartial %} - October CMS - 3.x","titleTemplate":false,"description":"Twig 标签","frontmatter":{"subtitle":"Twig 标签"},"headers":[{"level":2,"title":"简短更新语法","slug":"简短更新语法","link":"#简短更新语法","children":[]},{"level":2,"title":"延迟加载部件","slug":"延迟加载部件","link":"#延迟加载部件","children":[]},{"level":2,"title":"调用 AJAX 处理器","slug":"调用-ajax-处理器","link":"#调用-ajax-处理器","children":[{"level":3,"title":"捕获生命周期","slug":"捕获生命周期","link":"#捕获生命周期","children":[]}]}],"relativePath":"3.x/zh-cn/markup/tag/ajax-partial.md","filePath":"3.x/zh-cn/markup/tag/ajax-partial.md"}'),i={name:"3.x/zh-cn/markup/tag/ajax-partial.md"};function r(k,a,d,g,m,h){const t=n("pre-heading"),p=n("post-heading");return o(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"{% ajaxPartial %}",-1)),s(p),a[1]||(a[1]=u(`<div class="custom-block aside"><p>此标签扩展了 <a href="./partial.html"><code>{% partial %}</code> Twig 标签</a>。</p></div><p><code>{% ajaxPartial %}</code> 标签在页面上渲染部件内容，并包含对 <a href="./../../cms/ajax/introduction.html">AJAX 处理器</a>、自更新和简短更新语法的支持。这通常被称为自更新部件。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&quot;</span>contact-form<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>部件内容仅在首次加载时会被包裹在特定的 HTML 标签中。通过 AJAX 进行的后续部件更新不包含包裹标签。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">data-ajax-partial</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>contact-form<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    ... Contents go here ...
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="简短更新语法"><a href="#简短更新语法" class="header-anchor">#</a> 简短更新语法</h2><p>使用 AJAX 部件时，你不再需要指定选择器来更新它。只需在使用 <code>data-request-update</code> 属性时向<a href="./../../cms/ajax/attributes-api.html">数据属性 API</a> 传递 <code>true</code> 即可。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onRefresh<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ contact-form: true }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Refresh
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>你也可以使用 <code>_self</code> 作为部件名称从部件内部更新自身。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onRefresh<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: true }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Refresh
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>你还可以传递 <code>^</code> 符号来向容器前面添加内容，或传递 <code>@</code> 符号来向容器后面追加内容，而不是替换它。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onRefresh<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: &#39;@&#39; }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Append
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="延迟加载部件"><a href="#延迟加载部件" class="header-anchor">#</a> 延迟加载部件</h2><p><code>{% ajaxPartial %}</code> 接受一个 <code>lazy</code> 属性，该属性会将内容的渲染推迟到页面加载完成后。在以下示例中，<strong>posts</strong> 部件将在页面加载完成后更新。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>posts<span class="token punctuation">&#39;</span></span> lazy <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p><code>lazy body</code> 属性允许指定加载前的初始内容，后面跟着 <code>{% endpartial %}</code> 标签。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>posts<span class="token punctuation">&#39;</span></span> lazy body <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Loading posts...<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>需要注意的是，<code>{% ajaxPartial lazy %}</code> 标签不会立即渲染部件。相反，它输出一些初始内容，其中包含<a href="./../../cms/features/polling.html">轮询请求</a>使用的 <code>data-auto-submit</code> 数据属性。该属性会在页面加载后执行 AJAX 请求来加载部件内容。该属性不会包含在后续的部件更新中，以防止无限循环。</p><p>以下是首次页面加载时在浏览器中的显示方式：</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onAjax<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: true }<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-auto-submit</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Loading posts...<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>不要在你的部件中包含上述标记。<code>{% ajaxPartial lazy %}</code> 标签会自动为你包含它。</p></div><h2 id="调用-ajax-处理器"><a href="#调用-ajax-处理器" class="header-anchor">#</a> 调用 AJAX 处理器</h2><p>当从 AJAX 部件内部调用 AJAX 处理器时，会触发一个捕获页面生命周期（见下文），该生命周期允许在请求的部件中使用 AJAX 处理器。</p><p>以下示例展示了如何使用自更新部件提交一个简单的联系表单。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">description</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Self Updating Partial</span>&quot;</span>
</code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?</span>
<span class="token keyword">function</span> <span class="token function-definition function">onSubmitContactForm</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;submitted&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token delimiter important">?&gt;</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> submitted <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Thank you for contacting us!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSubmitContactForm<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: true }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Submit
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>使用 <a href="./../../cms/themes/components.html">CMS 组件</a>的部件也可以使用其 AJAX 处理器。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">contactForm</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>contactForm::onSubmit<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: true }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Submit
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><h3 id="捕获生命周期"><a href="#捕获生命周期" class="header-anchor">#</a> 捕获生命周期</h3><p>当从 AJAX 部件调用处理器时，会触发一个不同的生命周期，称为捕获生命周期。捕获生命周期渲染整个页面，但是将内容渲染到空白区域中。通过这种方式，页面被完整初始化，包括所有使用的部件和 AJAX 处理器。</p><p>由于这算作一次完整的页面渲染，这可能意味着在使用 AJAX 部件处理器时会调用 <code>onRun</code> <a href="./../../extend/cms-components.html">组件方法</a>。你可以使用 <code>Request::ajax()</code> <a href="./../../extend/services/request-input.html">辅助方法</a>来判断请求是否是 AJAX 请求的结果。</p>`,30))])}const x=e(i,[["render",r]]);export{q as __pageData,x as default};
